import django.core.validators
from django.db import migrations, models


def move_ipms_figures(apps, schema_editor):
    """Figures recorded before as "measured to IPMS" sat in the GIA, NIA and GEA boxes. Move them to the IPMS
    boxes they belong in (GEA to IPMS 1, GIA to IPMS 2, NIA to IPMS 3) with their source and date."""
    Property = apps.get_model("properties", "Property")
    for p in Property.objects.filter(area_standard="ipms"):
        p.ipms1_sqm, p.ipms2_sqm, p.ipms3_sqm = p.gea_sqm, p.gia_sqm, p.nia_sqm
        p.ipms_source, p.ipms_measured_on = p.area_source, p.areas_measured_on
        p.ipms_notes = "Moved from the GIA, NIA and GEA boxes, where it was recorded as measured to IPMS."
        p.gia_sqm = p.nia_sqm = p.gea_sqm = None
        p.area_standard, p.area_source, p.areas_measured_on = "", "", None
        p.save()


